UPDATE clarification_attachment
SET deleting_at = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND uploader_user_id = #{uploaderUserId}
  AND turn_id IS NULL
  AND deleting_at IS NULL
  AND id = #{id}

UPDATE clarification_attachment
