  AND id = #{id}
  AND turn_id IS NULL
  AND deleting_at IS NULL

mapper.delete:
DELETE FROM clarification_attachment
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND id = #{id}
  AND deleting_at IS NOT NULL
